    \"\"\"Raised when OpenAI returns an unsuccessful or invalid response.\"\"\"

    def __init__(
        self,
        message: str,
        *,
        status_code: Optional[int] = None,
        error_type: Optional[str] = None,
        error_code: Optional[str] = None,
        request_id: Optional[str] = None,
    ) -> None:
        super().__init__(message)
        self.status_code = status_code
        self.error_type = error_type
        self.error_code = error_code
        self.request_id = request_id


class OpenAIClient:
    \"\"\"A minimal, non-streaming client for the OpenAI Responses API.\"\"\"

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        *,
        model: Optional[str] = None,
        timeout: float = DEFAULT_TIMEOUT,
    ) -> None:
        self._api_key = _resolve_api_key(api_key)
        self.model = _resolve_model(model)
        self.timeout = _validate_timeout(timeout)

    def send_prompt(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        store: bool = False,
    ) -> str:
        \"\"\"Send one text prompt and return the assistant's text output.\"\"\"

        response = self.create_response(
            prompt,
            model=model,
            instructions=instructions,
            store=store,
        )
        return extract_text(response)

    def create_response(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        store: bool = False,
    ) -> Dict[str, Any]:
        \"\"\"Send one text prompt and return the decoded API response object.\"\"\"

        if not isinstance(prompt, str):
            raise ConfigurationError(\"prompt must be a string\")
        if not prompt:
            raise ConfigurationError(\"prompt must not be empty\")
        if instructions is not None and not isinstance(instructions, str):
            raise ConfigurationError(\"instructions must be a string or None\")
        if not isinstance(store, bool):
            raise ConfigurationError(\"store must be a bool\")

        selected_model = _resolve_model(model, fallback=self.model)
        payload: Dict[str, Any] = {
            \"model\": selected_model,
            \"input\": prompt,
            \"store\": store,
        }
        if instructions is not None:
            payload[\"instructions\"] = instructions

        try:
            encoded_payload = json.dumps(
                payload,
                ensure_ascii=False,
                allow_nan=False,
                separators=(\",\", \":\"),
            ).encode(\"utf-8\")
        except (TypeError, ValueError) as exc:
            raise ConfigurationError(\"request payload is not JSON serializable\") from exc

        request = Request(
            API_ENDPOINT,
            data=encoded_payload,
            headers={
                \"Accept\": \"application/json\",
                \"Authorization\": \"Bearer {}\".format(self._api_key),
                \"Content-Type\": \"application/json\",
                \"User-Agent\": \"openai-responses-standard-library-client/1.0\",
            },
            method=\"POST\",
        )

        try:
            with urlopen(request, timeout=self.timeout) as raw_response:
                response_body = raw_response.read()
        except HTTPError as exc:
            raise _api_error_from_http(exc) from None
        except (socket.timeout, TimeoutError) as exc:
            raise TransportError(\"the request timed out\") from exc
        except URLError as exc:
            if isinstance(exc.reason, (socket.timeout, TimeoutError)):
                raise TransportError(\"the request timed out\") from exc
            raise TransportError(\"the request could not be completed\") from exc
        except OSError as exc:
            raise TransportError(\"the request could not be completed\") from exc

        response = _decode_json_object(response_body)
        error = response.get(\"error\")
        if isinstance(error, Mapping):
            raise _api_error_from_object(
                error,
                status_code=None,
                request_id=None,
            )
        return response


