    prompt: str,
    *,
    api_key: [REDACTED_SECRET] = None,
    model: Optional[str] = None,
    instructions: Optional[str] = None,
    timeout: float = DEFAULT_TIMEOUT,
    store: bool = False,
) -> str:
    \"\"\"Send one text prompt and return the assistant's text output.\"\"\"

    client = OpenAIClient(api_key, model=model, timeout=timeout)
    return client.send_prompt(
        prompt,
        instructions=instructions,
        store=store,
    )


def extract_text(response: Mapping[str, Any]) -> str:
    \"\"\"Extract output text from a decoded Responses API response.\"\"\"

    if not isinstance(response, Mapping):
        raise APIError(\"the API response was not a JSON object\")

    output = response.get(\"output\")
    text_parts = []

    if isinstance(output, Sequence) and not isinstance(output, (str, bytes)):
        for item in output:
            if not isinstance(item, Mapping) or item.get(\"type\") "'!= "message":
                continue
            content = item.get("content")
            if not isinstance(content, Sequence) or isinstance(
                content, (str, bytes)
            ):
                continue
            for content_item in content:
                if not isinstance(content_item, Mapping):
                    continue
                if content_item.get("type") == "output_text":
                    text = content_item.get("text")
                    if isinstance(text, str):
                        text_parts.append(text)

    if text_parts:
        return "".join(text_parts)

    output_text = response.get("output_text")
    if isinstance(output_text, str):
        return output_text

    incomplete_details = response.get("incomplete_details")
    if isinstance(incomplete_details, Mapping):
        reason = incomplete_details.get("reason")
        if isinstance(reason, str) and reason:
            raise APIError(
                "the response is incomplete ({}) and contains no text".format(reason)
            )
    raise APIError("the API response contains no output text")


