    if not isinstance(selected_model, str) or not selected_model.strip():
        raise ConfigurationError(
            "a model is required; pass model=... or set OPENAI_MODEL"
        )
    return selected_model.strip()


def _validate_timeout(timeout: float) -> float:
    if isinstance(timeout, bool) or not isinstance(timeout, (int, float)):
        raise ConfigurationError("timeout must be a positive number")
    if timeout <= 0:
        raise ConfigurationError("timeout must be a positive number")
    return float(timeout)


def _decode_json_object(raw_body: bytes) -> Dict[str, Any]:
    try:
        decoded = json.loads(raw_body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise APIError("the API returned malformed JSON") from exc
    if not isinstance(decoded, dict):
        raise APIError("the API response was not a JSON object")
    return decoded


def _api_error_from_http(error: HTTPError) -> APIError:
    request_id = error.headers.get("x-request-id") if error.headers else None
    try:
        raw_body = error.read(MAX_ERROR_BODY_BYTES)
    except OSError:
        raw_body = b""

    error_object: Mapping[str, Any] = {}
    if raw_body:
        try:
            decoded = json.loads(raw_body.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            decoded = None
        if isinstance(decoded, Mapping):
            nested_error = decoded.get("error")
            if isinstance(nested_error, Mapping):
                error_object = nested_error

    return _api_error_from_object(
        error_object,
        status_code=error.code,
        request_id=request_id,
        fallback_message="OpenAI returned an unsuccessful HTTP response",
    )


def _api_error_from_object(
    error_object: Mapping[str, Any],
    *,
    status_code: Optional[int],
    request_id: Optional[str],
    fallback_message: str = "OpenAI returned an API error",
) -> APIError:
    error_type = error_object.get("type")
    error_code = error_object.get("code")
    if not isinstance(error_type, str):
        error_type = None
    if not isinstance(error_code, str):
        error_code = None

    details = []
    if status_code is not None:
        details.append("HTTP {}".format(status_code))
    if error_type:
        details.append(error_type)
    if error_code:
        details.append(error_code)
    if request_id:
        details.append("request_id={}".format(request_id))

    message = fallback_message
    if details:
        message = "{} ({})".format(message, ", ".join(details))
    return APIError(
        message,
        status_code=status_code,
        error_type=error_type,
        error_code=error_code,
        request_id=request_id,
    )


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description=(
            "Send a private text prompt to OpenAI'"'s Responses API. \"
            \"The API key is read only from OPENAI_API_KEY.\"
        )
    )
    parser.add_argument(
        \"prompt\",
        nargs=\"*\",
        help=\"prompt text; when omitted, read the prompt from standard input\",
    )
    parser.add_argument(
        \"--model\",
        help=\"model ID; falls back to OPENAI_MODEL\",
    )
    parser.add_argument(
        \"--instructions\",
        help=\"optional system-style instructions\",
    )
    parser.add_argument(
        \"--timeout\",
        type=float,
        default=DEFAULT_TIMEOUT,
        help=\"HTTPS request timeout in seconds (default: %(default)s)\",
    )
    return parser


def main(argv: Optional[Sequence[str]] = None) -> int:
    \"\"\"Run the command-line interface and return a process exit status.\"\"\"

    parser = _build_parser()
    args = parser.parse_args(argv)

    if args.prompt:
        prompt = \" \".join(args.prompt)
    elif not sys.stdin.isatty():
        prompt = sys.stdin.read()
    else:
        parser.error(\"provide a prompt argument or pipe one on standard input\")

    if not prompt:
        parser.error(\"prompt must not be empty\")

    try:
        answer = send_prompt(
            prompt,
            model=args.model,
            instructions=args.instructions,
            timeout=args.timeout,
        )
    except OpenAIError as exc:
        print(\"error: {}\".format(exc), file=sys.stderr)
        return 1

    sys.stdout.write(answer)
    if not answer.endswith(\"\\n\"):
        sys.stdout.write(\"\\n\")
    return 0


if __name__ == \"__main__\":
    raise SystemExit(main())
